// agents/knowledge/librarian/agent.ts — proposed definition
export default defineAgent({
  name: "librarian",
  description: "Condenses inbound material (transcripts+checkpoints, PRs, discord) into attempts and learnings; catalogs into the knowledge ledger.",
  model: "codex-lb/gpt-5.6-sol",   // judgment-heavy: same tier as workers, not curator's 5.5
  thinking: "medium",               // "high" for the corroboration pass
  coreTools: ["read", "grep", "code_graph_search", "past_prs_search", "ledger_append", "ledger_search"],
  extensions: false,
  canSpawnSubagent: false,
  runInBackground: true,
});
// schema.json: learning proposals (subject+scope, origin, statement, evidence[], confidence)
//            + attempt overlays (checkpoint_id, tactics[{tactic, outcome, at}])
//            + verdicts on existing learnings (confirm | refute)
